INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'adjust.note', 'de', 'Änderungen gelten nur auf dieser Seite &mdash; nichts wird gespeichert, und ein Neuladen stellt den rückwärts geplanten Zeitplan wieder her. Ein Land, das Sie hinter seine eigene Frist schieben, bleibt sichtbar und wird oben ausgewiesen, denn ein Plan, der einen Termin reißt, ist eine Entscheidung und kein Fehler.');
