INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.durations', 'de', 'Die Dauern gelten je Land. Länder mit gemeinsamem Go-live-Termin bilden eine Welle, eine Welle aus fünf Ländern kostet also rund fünf Länder-Arbeitsstränge an Aufwand, verteilt auf so viele Arbeitsstränge, wie Sie tatsächlich gleichzeitig fahren können.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.grades', 'de', 'Jede Zahl zeigt, woher sie stammt. <span class="tag tA">A</span> gemessen und primär &middot; <span class="tag tB">B</span> glaubwürdige Institution, ohne Quellenangabe &middot; <span class="tag tD">D</span> unsere Schätzung. Ein Wert von Ihnen schlägt unseren Standardwert immer &mdash; genau dafür ist dieses Panel da.');
