INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.placeholders', 'de', 'Diese Zahlen sind <strong>nur Platzhalter</strong>. Bitte ersetzen Sie sie durch Budgetschätzungen Ihres Anbieters und behandeln Sie den ROI als beispielhaft, bis Ist-Werte vorliegen.');
