INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.ap.just2', 'de', ' Der Compliance werden nur Erfassung und Prüfung zugerechnet &mdash; 9 der 21 Minuten AP-Bearbeitung {0} &mdash; weil Sichtung und Freigabe unternehmerische Entscheidungen sind, die kein Rechnungsformat abschafft.');
