INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.arShare2.just', 'de', 'Ausstellungskosten aus den ATO-Kanalzahlen {0} auf deren eigener 60/40-Aufteilung {1}. Senkungsspanne {2}. Der Anteil strukturierter Ausstellung ist Ihrer, und unser Standardwert ist bewusst der höchste verfügbare Messwert {3}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.cycle2.just', 'de', 'Lieferantenrückfragen binden <strong>12,8 %</strong> der AP-Arbeitszeit gegenüber <strong>24,0 %</strong> {0}; Durchlaufzeit <strong>2,9 Tage</strong> gegenüber <strong>13,5</strong> {1}; <strong>15 % weniger Rückfragen</strong> bei einem Trust {2}. Zusammenhänge mit leistungsstarker Kreditorenbuchhaltung, keine gemessenen Wirkungen.');
