INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.penalty.just', 'de', '{0} Ihrer Länder veröffentlichen einen bezifferten Bußgeldkatalog {1}. Bemessen Sie das je Land; einen glaubwürdigen Gesamtwert gibt es nicht.');
