INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.excSplit', 'de', '11,1 % gegenüber 20,9 %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA', 'de', 'Note A');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA.body', 'de', 'Ardent Partners 2025 (Kosten, Durchlaufzeit, Ausnahme- und Lieferantenrückfragequoten) &middot; ATO / Deloitte Access Economics (Papier gegenüber PDF gegenüber E-Rechnung, Stand 2016, ausgewiesen) &middot; OECD DCTR 2026 (Wirkmechanismus) &middot; die Tracker-Daten dieser Seite.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA.tag', 'de', 'gemessen &amp; primär');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB', 'de', 'Note B');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB.body', 'de', 'HMRC/DBT: 60&ndash;80 % Kostensenkung und rund 10 % manuelle Fehlerquote. Beides steht in einer Konsultation der britischen Regierung, keines davon mit einer Quelle darin. Hier verwendet, mit dieser Lücke im Protokoll.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB.tag', 'de', 'glaubwürdige Institution, ohne Quellenangabe');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC', 'de', 'Note C');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC.body', 'de', 'Die Zahlen des NHS-Trusts (24 Stunden statt 10 Tage, doppelte Zahlungsgeschwindigkeit, 15 % weniger Rückfragen) stammen von einer einzelnen, nicht genannten und nicht datierten Organisation. Die Zahlen zur Umsatzsteuerlücke kommen von der Europäischen Kommission und CASE, nicht von der OECD, und deren eigene Länderanalysen führen die Veränderung auf die konjunkturelle Erholung zurück, nicht auf die digitale Meldung.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC.tag', 'de', 'Anekdote, kein Benchmark');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD', 'de', 'Note D');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD.body', 'de', 'Die Bearbeitungszeit je fehlerhafter Rechnung, die Vollkostensätze, der Anteil des Steueraufwands. Das sind unsere Ausgangsschätzungen, offengelegt, damit Sie sie durch Ihre eigenen ersetzen können.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD.tag', 'de', 'Ihre Annahme');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeLabel', 'de', 'Nachweisgrad {0}');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.hmrcAto', 'de', 'HMRC, durch ATO bestätigt');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.hmrcRate', 'de', 'HMRC-Konsultation');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.nhsQuery', 'de', '15 % weniger Rückfragen');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.oecdDctr', 'de', 'OECD DCTR, 2026');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.ourAssumption', 'de', 'unsere Annahme');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.site.body', 'de', 'Die Daten zu den Vorgaben stammen aus dem eigenen Tracker dieser Seite: Status, Modell und datierte Fristen je Land, jeweils nachvollziehbar bis zum zitierten Rechtsakt im Länderprofil &mdash; das ist die Zusicherung, nicht etwa eine Aussage darüber, wie kürzlich geprüft wurde.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.siteLabel', 'de', 'Quelle: Tracker-Daten');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.sourceLink', 'de', 'Quelle');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.taskSplit', 'de', 'die Aufgabenaufteilung');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.trackerDates', 'de', 'Tracker-Termine');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.treasury', 'de', 'Nutzen Sie für alles, was Sie unterschreiben, Ihren eigenen Treasury-Satz');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.whyNot', 'de', 'warum nicht');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.whyNotAll', 'de', 'warum nicht alle');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourCall', 'de', 'Ihre Entscheidung');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourMins', 'de', 'Ihre Bearbeitungszeit');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourShare', 'de', 'Ihre Zahl');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yours.body', 'de', 'Ihre Annahme. Für diese Zahl wird nichts behauptet &mdash; sie liegt offen, damit man mit dem Modell streiten kann, statt ihm zu glauben.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'footer.pdf', 'de', 'Dieses Werkzeug modelliert einen Business Case; es ist keine Steuer-, Rechts- oder Anlageberatung. Mit D gekennzeichnete Zahlen sind unsere Ausgangsschätzungen und keine Benchmarks &mdash; ersetzen Sie sie durch Ihre eigenen, bevor eine Entscheidung darauf beruht.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'footer.text', 'de', '<strong>The E-Invoicing Compliance Corner</strong> &mdash; ROI- &amp; Wellenplaner. Jeder Termin einer Vorgabe ist hier bis zum zitierten Rechtsakt im Länderprofil des jeweiligen Landes nachvollziehbar, und dort ist er auch zu prüfen. Benchmark-Zahlen tragen den jeweils ausgewiesenen Nachweisgrad. Dieses Werkzeug modelliert einen Business Case; es ist keine Steuer-, Rechts- oder Anlageberatung.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'fx.converted', 'de', 'Umgerechnet zu einem <strong>festen Kurs</strong> von 1 {0} = {1} USD &mdash; nicht täglich aktualisiert.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'fx.convertedDated', 'de', 'Umgerechnet zu einem <strong>festen Kurs</strong> von 1 {0} = {1} USD, Kassakurs {2} &mdash; nicht täglich aktualisiert.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.body2', 'de', 'Ihre Zahlen stehen oben und gehören Ihnen. Ein kostenloses Konto speichert die von Ihnen gewählten Länder, benachrichtigt Sie per E-Mail, sobald sich eine dieser Vorgaben tatsächlich ändert, und merkt sich Ihre Annahmen für das nächste Mal. Dafür genügt ein 6-stelliger Code, kein Passwort &mdash; und Sie bleiben auf dieser Seite.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.cta2', 'de', 'Kostenloses Konto erstellen');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.eyebrow', 'de', 'Kostenloses Konto');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.signin', 'de', 'Schon eines? {0}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.signin.link', 'de', 'Anmelden');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.title', 'de', 'Behalten Sie das &mdash; und erfahren Sie, wenn es sich ändert');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'grp.named', 'de', 'Benannt, nicht beziffert &mdash; real, aber dieses Modell erfindet dafür keine Zahl');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'grp.priced', 'de', 'Beziffert &mdash; im Business Case berücksichtigt');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.capture', 'de', '<strong>Der Personalaufwand für die Erfassung ist mehr wert als die gesamte Bearbeitungseinsparung.</strong> {0} freigesetzte Erfassungskosten stehen {1} Gesamtsenkung der AP-Bearbeitung gegenüber. Das sind zwei Wege zum selben Geld, der erste kann den zweiten also nicht übersteigen &mdash; prüfen Sie den Satz für die Datenerfassung und die AP-Kosten je Rechnung, denn einer von beiden stimmt nicht.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.excGap', 'de', '<strong>Dieses Modell beseitigt mehr Ausnahmen, als das beste Viertel der Kreditorenbuchhaltungen von allen anderen trennt.</strong> Ihre Fehlerquote und Ihre Beseitigungsannahme nehmen zusammen {0} Prozentpunkte der Rechnungen aus der Ausnahmebehandlung; Ardent misst die gesamte Lücke zwischen Best-in-Class und allen anderen mit {1} Punkten {2}, über sämtliche Ursachen hinweg und mit E-Invoicing als nur einem Faktor. Senken Sie die Fehlerquote oder den Beseitigungsanteil &mdash; so wie es steht, beansprucht die Zeile zur Nacharbeit mehr, als die besten Marktteilnehmer erreichen.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.heading', 'de', '{0} {1} vor der Verwendung dieser Zahlen zu prüfen');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.late.one', 'de', '<strong>{0} fester Starttermin endet nach der Frist.</strong> {1}. Das kann Absicht sein &mdash; eine bewusst in Kauf genommene Verspätung ist eine Entscheidung, die eine Geschäftsleitung treffen kann &mdash; aber der Plan unten hält diesen Termin nicht mehr ein.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.late.other', 'de', '<strong>{0} feste Starttermine enden nach der Frist.</strong> {1}. Das kann Absicht sein &mdash; eine bewusst in Kauf genommene Verspätung ist eine Entscheidung, die eine Geschäftsleitung treffen kann &mdash; aber der Plan unten hält diese Termine nicht mehr ein.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.disc', 'de', '{0} &mdash; {1} (als frei planbar eingeplant)');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.one', 'de', '<strong>{0} ausgewähltes Land hat eine Verpflichtung, die früher greift als der Termin, für den dieser Plan plant.</strong> {1}. Das sind datierte, geltende Verpflichtungen, die der öffentliche Tracker dieser Seite nicht anzeigt, der Wellenplan plant sie also nicht ein. Der dafür angezeigte Vorlauf ist länger als der tatsächlich vorhandene.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.other', 'de', '<strong>{0} ausgewählte Länder haben Verpflichtungen, die früher greifen als der Termin, für den dieser Plan plant.</strong> {1}. Das sind datierte, geltende Verpflichtungen, die der öffentliche Tracker dieser Seite nicht anzeigt, der Wellenplan plant sie also nicht ein. Der dafür angezeigte Vorlauf ist länger als der tatsächlich vorhandene.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.planned', 'de', '{0} &mdash; {1} (geplant für {2})');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.payback', 'de', '<strong>Amortisation in unter einem Monat.</strong> Kein E-Invoicing-Programm amortisiert sich so schnell. Prüfen Sie die Volumina und die Kosten je Rechnung &mdash; eine dieser Größen liegt um eine Zehnerpotenz daneben, und der Rest dieser Seite erbt den Fehler.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.selectFirst', 'de', '<strong>Wählen Sie zuerst mindestens ein Land.</strong> Der Wellenplan, die Zahl der Integrationen und die gesamte Investitionsseite bauen auf den Ländern auf, in denen Sie fakturieren &mdash; ohne Auswahl gibt es kein Programm zu kalkulieren.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.soon', 'de', '<strong>{0} muss innerhalb von 90 Tagen beginnen</strong>, um die veröffentlichte Frist bei Ihren aktuellen Phasenannahmen zu halten.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.taxCap', 'de', '<strong>Die Einsparung beim Steueraufwand ist gedeckelt, und der Deckel greift.</strong> {0} würde {1} % Ihres AP-Aufwands bedeuten; das Modell rechnet höchstens {2} % an, weil die Größenordnung unsere Annahme ist und kein Benchmark und ein ungedeckelter Wert davonliefe. Weitere Länder verändern die indirekte Zahl nicht &mdash; sie erhöhen aber weiter die Kosten, und das ist die ehrliche Asymmetrie.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.zeroInt.one', 'de', '<strong>{0} ausgewähltes Land hat eine Vorgabe, das Modell hat aber null Integrationen kalkuliert.</strong> Das ist kein günstiges Programm, das ist eine kaputte Berechnung &mdash; behandeln Sie jede Zahl unten als unsicher, bis das erklärt ist.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.zeroInt.other', 'de', '<strong>{0} ausgewählte Länder haben eine Vorgabe, das Modell hat aber null Integrationen kalkuliert.</strong> Das ist kein günstiges Programm, das ist eine kaputte Berechnung &mdash; behandeln Sie jede Zahl unten als unsicher, bis das erklärt ist.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.arShare', 'de', 'Der Anteil der Rechnungen, die Sie AUSSTELLEN und die bereits als strukturierte E-Rechnung hinausgehen — nicht PDFs per E-Mail, die der Empfänger weiterhin lesen und erfassen muss. Eine Einsparung lässt sich nur einmal heben; was strukturiert hinausgeht, hat sie bereits gehoben. Standard 64 %: Billentis nennt für Europa diesen Wert, weltweit 29 %.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cImplC', 'de', 'Einmalige Kosten, um ein Abrechnungssystem an ein KOMPLEXES Land anzubinden — Clearance oder Meldung, also Zertifizierung, Fehlerbehandlung und Statusabgleich. Ein Platzhalter, wie oben. Ersetzen Sie ihn durch Ihr Angebot.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cImplS', 'de', 'Einmalige Kosten, um ein Abrechnungssystem an ein EINFACHES Land anzubinden — ein 4-Corner-Austausch, ohne die Steuerbehörde. Ein Platzhalter: Kein Analystenhaus veröffentlicht dazu eine glaubwürdige länderspezifische Zahl. Ersetzen Sie ihn durch Ihr Angebot.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cPlat', 'de', 'Jährliche Gebühren für Plattform, Netzwerk oder Zugangspunkt über alle Länder im Umfang. Hergeleitet aus einem Satz je Dokument auf Ihre AP- und AR-Volumina zusammen. Ein Platzhalter — Anbieterpreise unterscheiden sich um eine Zehnerpotenz. Ein selbst eingetragener Wert folgt den Volumina nicht mehr.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cRun', 'de', 'Ihre eigenen jährlichen Kosten für den Betrieb nach dem Go-live: Überwachung, Ausnahmebehandlung und das Nachhalten von Änderungen der Vorgaben. Ein Platzhalter, und meist unterschätzt — die Arbeit an den Vorgaben hört nie auf.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.colBanks', 'de', 'Ob eine Einsparung schon mit dem Compliance-Aufbau anfällt oder ein breiteres AP-Veränderungsprogramm braucht, das Sie vielleicht nicht fahren. Strukturierte Rechnungen buchen und klären sich ohne ein solches; ein neu geschnittener Workflow nicht. Jede Zeile sagt in ihrer Begründung, was gilt und warum.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.complexity', 'de', 'KOMPLEX, wo die Steuerbehörde Daten auf Rechnungsebene sieht: Clearance, ein 5-Corner-Modell oder digitale Meldung. Sonst EINFACH. Je Land im Tracker von Hand zugeordnet, nicht aus Fließtext abgeleitet. Bestimmt sowohl den Integrationssatz als auch die Phasendauern.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.costAR', 'de', 'Kosten, um heute eine Kundenrechnung auszustellen. Niedriger als der AP-Wert, weil beim Ausstellen Abgleich und Freigabe entfallen. Hergeleitet aus den ATO-/Deloitte-Kanalkosten über die 60/40-Aufteilung der ATO selbst (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.costNow', 'de', 'Vollkosten für die Bearbeitung einer Lieferantenrechnung heute — Personal, Systeme, Ausnahmen, Freigaben, nicht nur Lizenzen. Bildet die Basis, auf die die Senkung angewendet wird. Marktdurchschnitt von Ardent Partners, Daten 2025 (Note A).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.countries', 'de', 'Aktuelle Daten zu den Vorgaben aus dem eigenen Tracker dieser Seite — Status, Modell und datierte Frist je Land, jeweils nachvollziehbar bis zum zitierten Rechtsakt im Länderprofil. Die Eingabe, die das Ergebnis am stärksten verändert.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cur', 'de', 'Rechnet jeden Geldbetrag auf der Seite um, einschließlich der Benchmark-Standardwerte und aller von Ihnen überschriebenen Werte. Der Kurs ist ein zum angezeigten Datum erfasster und gespeicherter Kassakurs, nicht täglich aktualisiert, damit dasselbe Szenario Monate später dieselbe Antwort gibt. Nutzen Sie für alles, was Sie unterschreiben, Ihren eigenen Treasury-Satz.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.eShare', 'de', 'Der Anteil Ihrer Lieferantenrechnungen, die bereits als strukturierte E-Rechnung eingehen — nicht PDFs, die weiterhin gelesen und erfasst werden müssen. Eine Einsparung lässt sich nur einmal heben, das ist also der größte einzelne Hebel auf die AP-Zeile. Ardent nennt für den Markt 51 % (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.erp', 'de', 'Verschiedene ERP- oder Abrechnungssysteme, die Rechnungen senden oder empfangen müssen — nicht Rechtseinheiten; Einheiten mit gemeinsamem System zählen einmal. Jedes System nach dem ersten erhöht Design und Aufbau um 12 %, gedeckelt bei +60 %.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errElim', 'de', 'Welchen Anteil der heute fehlerhaften Rechnungen E-Invoicing tatsächlich beseitigt. Standard 80 % statt 100 %, weil Streitfälle und Unterlieferungen eine Rechnung stoppen, in welchem Format sie auch eingegangen ist. Unsere Annahme (Note D).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errMins', 'de', 'Tatsächliche Bearbeitungszeit für eine Rechnung mit fehlerhaften Daten: beim Lieferanten nachfassen, neu erfassen, erneut freigeben lassen. Bewertet mit dem Satz für die Datenerfassung unten. ATO: 15 Minuten für eine Bearbeitungsausnahme, 5 für eine reine Erfassungskorrektur (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errRate', 'de', 'Anteil der manuell bearbeiteten Rechnungen mit einem Fehler, der Nacharbeit erfordert. Bemisst die Zeile zur Nacharbeit. HMRC-/DBT-Konsultation 2025, die 10 % behauptet und dafür keine Studie zitiert (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.fteCost', 'de', 'Jährliche Vollkosten einer Vollzeitkraft in Steuern oder Finanzen. Bemisst allein die indirekte Einsparung beim Steueraufwand und ist gedeckelt. Bewusst nicht der Erfassungssatz daneben — rund doppelt so hoch und selten ausgelagert. BLS-Lohn, belastet mit dem BLS-Arbeitgeberkostenfaktor (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.fteEntry', 'de', 'Jährliche Vollkosten der Erfassungs- oder Poststellenrolle, die Lieferantenrechnungen aufnimmt. Stellt die Bearbeitungseinsparung in Personalkapazität dar; sie fügt nichts Eigenes hinzu. BLS Data Entry Keyers, belastet (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.integrations', 'de', 'Jedes Land, für das Sie bauen müssen, gezählt je ERP- oder Abrechnungssystem und bewertet mit seinem einfachen oder komplexen Satz. Nach den ersten Ländern werden keine Skaleneffekte modelliert, was diese Zahl eher konservativ als optimistisch macht.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.lanes', 'de', 'Wie viele Länder-Arbeitsstränge Sie tatsächlich gleichzeitig besetzen können. Verändert Laufzeit und spätesten verantwortbaren Start, nie den Gesamtaufwand. Unterstellt gleichbleibende Kapazität — ohne Lernkurve zwischen den Ländern.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.nomandate', 'de', 'Von Ihnen ausgewählte Länder, die heute keine Verpflichtung tragen, bewertet zum einfachen Satz. Sie teilen sich das Band ohne feste Frist mit Ländern, in denen die Vorgabe bereits vollständig in Kraft ist — optional sind aber nur diese. Die anderen sind zu spät dran.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.pace', 'de', 'Ein Multiplikator auf jede Phasendauer. Ambitioniert (×0,75) unterstellt eine erprobte Plattform und ein dediziertes Team; Konservativ (×1,3) unterstellt geteilte Ressourcen und normale Governance. Ein Ermessensregler, kein Benchmark.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.savePct', 'de', 'Wie viel der Kosten je Rechnung die Automatisierung beseitigt, angewendet auf die AP- und die AR-Basis. Standard 60 %, die Untergrenze der Spanne von 60–80 % der HMRC; die Kanalkosten der ATO legen unabhängig davon 67–70 % nahe (Note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.scope', 'de', 'Nur Compliance modelliert die Vorgabe als IT-Arbeitsstrang, und das kaufen die meisten Programme: Erfassung und Ausstellung werden eingespart, Sichtung und Freigabe nicht. Der größere Umfang ergänzt die Prozessneugestaltung und eine Umstellungsphase in jedem Länder-Arbeitsstrang.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.vida', 'de', 'Die Richtlinie (EU) 2025/516 des Rates macht strukturierte E-Rechnungen und digitale Meldung für den innergemeinschaftlichen B2B-Verkehr ab dem 1. Juli 2030 verpflichtend und bindet alle 27 Mitgliedstaaten, ob sie national gesetzgeberisch tätig geworden sind oder nicht. Als KOMPLEX bewertet, weil sie eine Meldepflicht enthält.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.volAP', 'de', 'In einem Jahr eingegangene Lieferantenrechnungen über alle Einheiten im Umfang. Zählen Sie Dokumente, nicht Bestellungen oder Positionen — jeder Benchmark hier gilt je Dokument. Bestimmt die AP-Einsparung und die Zeile zur Nacharbeit.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.volAR', 'de', 'Kundenrechnungen, die Sie in einem Jahr ausstellen. Daran setzen die Vorgaben an: Clearance- und Melderegime steuern, was Sie senden, nicht was Sie empfangen. Bestimmt die AR-Einsparung.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.arShare', 'de', 'Heute ausgestellte E-Rechnungen %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cImplC', 'de', 'Kosten je KOMPLEXER Integration');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cImplS', 'de', 'Kosten je EINFACHER Integration');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cPlat.derived', 'de', 'Näherungswert: {vol} Rechnungen &times; {fee} je Stück. Das ist ein grober Multiplikator je Rechnung für die Technologie &mdash; der tatsächliche Preis Ihres Anbieters weicht davon ab und sollte hier eingetragen werden.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cPlat2', 'de', 'Softwaregebühren p. a.');
