INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'score.durations', 'de', '<strong>Und jeder Termin im Wellenplan beruht auf einer Note D.</strong> Die Phasendauern sind {0}, weil kein Analystenhaus glaubwürdige länderspezifische Umsetzungsdauern veröffentlicht &mdash; das wurde geprüft. Sie können sie im selben Panel ändern.');
