INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.emptyChart', 'de', 'Kein ausgewähltes Land hat sowohl eine künftige datierte Frist als auch eine Vorgabe, für die zu bauen wäre, es gibt also keine Umsetzungszeitachse darzustellen. Länder, in denen die Vorgabe bereits in Kraft ist, brauchen dennoch Nacharbeit &mdash; siehe die Tabelle unten.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.emptyTable', 'de', 'Kein ausgewähltes Land hat eine künftige datierte Frist. Länder, in denen die Vorgabe bereits in Kraft ist, brauchen dennoch Nacharbeit &mdash; siehe die Liste der in Kraft befindlichen Vorgaben unten.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.euWide', 'de', 'Die Richtlinie (EU) 2025/516 des Rates bindet jeden EU-Mitgliedstaat ab dem 1. Juli 2030, unabhängig davon, ob er eine eigene nationale Vorgabe erlässt. {0}');
