INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro', 'de', 'Rückwärts geplant von der veröffentlichten Frist jedes Landes {0} über Phasendauern, die Sie steuern {1}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro3', 'de', 'Die Beschaffung wird einmal modelliert, nicht je Land.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro4', 'de', 'Eine dieser Wellen ist die EU-weite Verpflichtung und keine nationale Vorgabe; sie deckt die {0} ab, die Sie ausgewählt haben.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.noMandate', 'de', '<strong>Keine Vorgabe, auf Ihre Auswahl hin enthalten ({0}):</strong> {1}. Zum einfachen Satz kalkuliert und als eine frei planbare Welle eingeplant &mdash; es gibt keine Frist zu reißen, diese Arbeit kann also beginnen, sobald Kapazität da ist.');
