-- ---- 31 benchmarks: hint and citation, label NULL --------------------
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Marktdurchschnitt von Ardent Partners, Daten 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>, veröffentlicht am 22. Jan. 2026. Marktdurchschnittliche Kosten je Rechnung USD 9,84, erhoben unter 204 AP-Fachleuten. Frei zugänglich und primär.' FROM roi_benchmarks WHERE key = 'ap_cost_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Median des APQC Open Standards Benchmarking', 'APQC Open Standards Benchmarking, Kennzahl &ldquo;number of invoices processed per FTE that performs the process process accounts payable&rdquo;: <strong>Median 12.000 je Vollzeitkraft und Jahr</strong>. Primär, zurechenbar und auf der Kennzahlenseite öffentlich ausgewiesen; die Quartilswerte liegen hinter der APQC-Mitgliedschaft und werden hier nicht verwendet. APQC berichtet gesondert, dass Spitzenreiter rund fünfmal produktiver sind als das Schlusslicht, ein einzelner Median verdeckt also eine sehr große Spreizung &mdash; er dient in diesem Modell allein dazu, dem Rechnungsvolumen eine vertretbare Beziehung zur Personalstärke zu geben, nie dazu zu behaupten, was ein bestimmtes Unternehmen erreichen sollte.' FROM roi_benchmarks WHERE key = 'ap_invoices_per_fte';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Hergeleitet aus ATO-/Deloitte-Zahlen — siehe Quellenangabe', 'Hergeleitet aus <em>Peppol eInvoicing value assessment</em> der Australian Taxation Office / Deloitte Access Economics: Papier AUD 30,87, PDF AUD 27,67, E-Rechnung AUD 9,18, wobei die ATO ausdrücklich sagt, dies sei <strong>eine zwischen Rechnungssteller und Rechnungsempfänger geteilte Kostenschätzung</strong>. Die ATO veröffentlicht auch die Aufteilung &mdash; <strong>40 % auf die Debitoren-, 60 % auf die Kreditorenseite</strong> &mdash; der AR-Anteil ist also die Zurechnung der ATO selbst und nicht unsere.<br><br><strong>Note B, und bis zum 16. August 2026 aus dem falschen Grund.</strong> In der Quellenangabe stand früher, die Note B ergebe sich daraus, dass die Aufspaltung auf einen reinen AR-Wert unsere Herleitung sei. Das stimmt nicht: Die ATO veröffentlicht diese Aufteilung auf derselben Seite. Die wirklichen Gründe sind, dass die Schätzungen australisch sind, aus dem Jahr 2016 stammen, keine veröffentlichte Stichprobengröße tragen und die Umrechnung in US-Dollar von uns kommt. Dieselbe Note, ehrlich begründet &mdash; und die Korrektur war nötig, denn wer den Satz zur Aufteilung fand, hätte diese Zeile nach dem alten Wortlaut zu Recht auf A hochgestuft.' FROM roi_benchmarks WHERE key = 'ar_cost_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Billentis nennt für Europa 64 % und weltweit 29 % — wir setzen den höheren Wert als Standard', 'Der Anteil der Rechnungen, die Sie AUSSTELLEN und die bereits als strukturierte E-Rechnung hinausgehen. Nicht PDFs und nicht E-Mail: Ein Abrechnungssystem, das ein PDF verschickt, hat das Dokument digitalisiert und nicht die Transaktion, und die ATO setzt ein PDF mit AUD 27,67 an, gegenüber AUD 30,87 für Papier und AUD 9,18 für eine echte E-Rechnung.<br><br><strong>Billentis, <em>Riding the Tornado</em> (2026)</strong>, ist die einzige Quelle, die die AUSSTELLUNG misst und nicht den Empfang &mdash; sie zählt übertragenes Volumen, statt Posteingänge zu befragen. Von weltweit rund 300 Mrd. B2B-Rechnungen sind etwa 87&ndash;88 Mrd. elektronisch: <strong>29 % weltweit, rund 64 % in Europa, rund 78 % in Lateinamerika</strong>.<br><br><strong>Standard 64 %, und das ist bewusst der höchste uns verfügbare Wert.</strong> Die weltweite Messung liegt bei 29 %, und der empfangsseitige Anteil von Ardent legt 51 % nahe. Europas 64 % sind durch die Länder überzeichnet, die den Umstieg bereits hinter sich haben &mdash; Italien liegt nahe 97 % und kam per Vorgabe dorthin &mdash; der Wert ist also womöglich zu hoch für ein Land, dessen Vorgabe noch aussteht, und genau diesen Fall kalkuliert dieser Planer. Wir verwenden ihn dennoch, weil ein Business Case gegen sich selbst irren sollte. <strong>Senken Sie ihn, wenn Sie Ihre eigene Lage kennen</strong>; jeder Prozentpunkt weniger erhöht die ausgewiesene Einsparung.<br><br>Note B: Billentis ist eine glaubwürdige Institution, die das Richtige misst, aber die Zahlen erreichen uns über die veröffentlichten Zusammenfassungen des Berichts und nicht aus eigener Lektüre der Primärquelle, und der Nenner ist nicht unabhängig reproduzierbar.' FROM roi_benchmarks WHERE key = 'ar_einvoice_share_now';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Die ATO teilt die geteilten Kosten 60 AP / 40 AR auf', 'Australian Taxation Office, <em>Peppol eInvoicing value assessment</em>: Die dort veröffentlichten Kosten je Rechnung sind <strong>eine zwischen Rechnungssteller und Rechnungsempfänger geteilte Kostenschätzung</strong>, und die ATO hält fest, &ldquo;for the purposes of this assessment 40% of this cost is attributed to the accounts receivable process and 60% to accounts payable&rdquo;. Hier vorgehalten, weil zwei weitere Zahlen dieser Seite darauf beruhen. Note B, nicht A: Die ATO veröffentlicht die Aufteilung ohne Stichprobengröße und weist darauf hin, dass die zugrunde liegenden Schätzungen aus dem Jahr 2016 stammen.' FROM roi_benchmarks WHERE key = 'ato_ap_cost_share';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'ATO / Deloitte, Bearbeitungszeiten für Eingangsrechnungen', 'Australian Taxation Office / Deloitte Access Economics, <em>Peppol eInvoicing value assessment</em>: Der Prozess der Eingangsrechnung ist aufgeschlüsselt in Eingang 7 Minuten, Prüfung 2, Sichtung 7 und Freigabe 5 &mdash; zusammen 21 Minuten, davon <strong>9 Minuten (43 %) Eingang und Prüfung</strong>, also die Erfassungs- und Eingabearbeit, die E-Invoicing beseitigt. Dieselbe Seite hält fest, dass der Großteil der Papier- und PDF-Kosten &ldquo;is attributable to the manual work required to enter the invoice data into your systems&rdquo;, weshalb der Benchmark je Rechnung nicht ZUSÄTZLICH als Personaleinsparung gezählt werden darf. Sichtung und Freigabe liegen auf der Fachseite, und es wird nicht unterstellt, dass sie entfallen. Die ATO weist darauf hin, dass diese Zeiten aus dem Jahr 2016 stammen.' FROM roi_benchmarks WHERE key = 'capture_share_of_ap';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — es gibt keinen glaubwürdigen Benchmark', 'Ein Platzhalter, kein Benchmark. Kein Analystenhaus veröffentlicht glaubwürdige länderspezifische Umsetzungskosten für E-Invoicing &mdash; das wurde direkt geprüft. Ersetzen Sie den Wert durch Ihre eigenen Angebote, bevor Sie die Amortisationszahl jemandem zeigen.' FROM roi_benchmarks WHERE key = 'cost_per_integration';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — eine CTC- oder 5-Corner-Anbindung', 'Dans Praktikerschätzung für die Anbindung eines Abrechnungssystems an ein CTC- oder 5-Corner-Land, in dem die Steuerbehörde Partei der Transaktion ist. Kein Benchmark, aus demselben Grund wie beim einfachen Satz. Ersetzen Sie ihn durch ein Anbieterangebot.' FROM roi_benchmarks WHERE key = 'cost_per_integration_complex';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — eine dezentrale 4-Corner-Anbindung', 'Dans Praktikerschätzung für die Anbindung eines Abrechnungssystems an ein 4-Corner-Land. Kein Benchmark: Kein Analystenhaus veröffentlicht glaubwürdige länderspezifische Umsetzungskosten für E-Invoicing, was der Nachweis-Audit über zehn von ihnen hinweg bestätigt hat. Ersetzen Sie ihn durch ein Anbieterangebot.' FROM roi_benchmarks WHERE key = 'cost_per_integration_simple';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'HMRC 60–80 %; ATO-Kanaldaten legen 67–70 % nahe', 'HMRC-/DBT-Konsultation, 13. Feb. 2025: &ldquo;Industry estimates suggest that moving to e-invoicing reduces invoicing costs by 60-80%.&rdquo; <strong>HMRC nennt keine Studie</strong> &mdash; gegen die Primärkonsultation geprüft &mdash; und Ardent Partners veröffentlicht dieselbe Spanne für <em>vollständige AP-Automatisierung im Vergleich zu manuellen und papierbasierten Verfahren</em>, was ein größeres Programm ist als Compliance allein.<br><br><strong>Die Spanne wird gleichwohl gestützt, durch eine unabhängige Kanalmessung.</strong> Das Peppol value assessment der ATO setzt eine Papierrechnung mit AUD 30,87 an, ein PDF mit 27,67 und eine E-Rechnung mit 9,18. Diese Verhältnisse ergeben eine <strong>Senkung von 70,3 % gegenüber Papier und 66,8 % gegenüber PDF</strong> &mdash; skalenfrei, sodass Währung und Sender-/Empfänger-Aufteilung sie nicht berühren, und mitten in der Spanne der HMRC. Zwei unabhängige Quellen, zwei Methoden, eine Antwort.<br><br><strong>Standard 60 %, die Untergrenze statt der Mitte.</strong> Die ATO würde 67 % tragen. Ein konservativer Wert unterhalb einer bestätigten Spanne ist der bessere Ort als deren Mitte, und diesen Eingabewert dürfen Sie anheben, wenn Ihre Ausgangslage tatsächlich Papier ist.' FROM roi_benchmarks WHERE key = 'cost_reduction_pct';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Ardent Partners, Daten 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: marktdurchschnittliche Durchlaufzeit 8,2 Tage; Best-in-Class 2,9 Tage gegenüber 13,5 bei allen anderen. <strong>Bewusst NICHT als Beleg dafür angeboten, dass E-Invoicing die Durchlaufzeit verkürzt.</strong> Ardent definiert Best-in-Class als die 20 % der Unternehmen mit den niedrigsten Bearbeitungskosten und den &ldquo;shortest average invoice process times&rdquo; &mdash; die Durchlaufzeit ist Teil der Definition, die Lücke von 79 % ist also eine Tautologie und kein Befund. Die Zahl wird hier zitiert, damit sie im Protokoll steht, und der Grund, sich nicht auf sie zu stützen, ebenfalls.' FROM roi_benchmarks WHERE key = 'cycle_time_days';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'OECD, Jan. 2026 — Wirkmechanismus, keine Größenordnung', 'OECD, <em>Digital Continuous Transactional Reporting for Value Added Tax</em>, 9. Jan. 2026: DCTR &ldquo;typically requires the (near) real-time reporting of invoices or transactional data to tax authorities, most often with the objective of strengthening VAT compliance and risk management.&rdquo; Belegt den Wirkmechanismus; es handelt sich um Gestaltungshinweise und keine Wirkungsstudie, daher trägt sie keinen Prozentsatz.' FROM roi_benchmarks WHERE key = 'dctr_mechanism';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Der Marktdurchschnitt liegt bei 51 % — entscheidend ist Ihr eigener Wert', 'Der Anteil Ihrer Lieferantenrechnungen, die BEREITS als strukturierte E-Rechnung eingehen. Nicht PDFs: Ein PDF muss weiterhin gelesen und erfasst werden, und die ATO setzt es mit AUD 27,67 an, gegenüber AUD 30,87 für Papier und AUD 9,18 für eine echte E-Rechnung. <strong>Das ist der größte einzelne Hebel auf die Zeile der Bearbeitungskosten</strong>, weil eine Einsparung nur einmal gehoben werden kann &mdash; was bereits strukturiert eingeht, hat sie bereits gehoben. Auf Dans Vorgabe hin auf 50 % gesetzt, nahe am Marktdurchschnitt; setzen Sie ihn auf Ihre eigene Lage, und auf 0, wenn Sie bei null anfangen.' FROM roi_benchmarks WHERE key = 'einvoice_share_now';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Unsere Annahme — bewusst nicht 100 %', 'Unsere Annahme, kein Benchmark. Strukturierte Rechnungsdaten beseitigen Erfassungsfehler am Ort der Erfassung, aber <strong>nicht jede Ausnahme ist ein Erfassungsfehler</strong> &mdash; ein strittiger Preis, eine Unterlieferung oder eine fehlende Bestellung hält eine Rechnung weiterhin auf, so sauber die Daten auch eingegangen sind, und kein Format löst eine kaufmännische Meinungsverschiedenheit. 80 % ist ein bewusster Abschlag auf die Annahme, dass der größte Teil der heutigen Ausnahmelast Datenqualität ist, nicht die gesamte.<br><br><strong>Was Ardent stützt und was nicht.</strong> Ardent Partners benennt den Wirkmechanismus direkt &mdash; &ldquo;eInvoicing drives process efficiencies by eliminating data capture and manual data entry&rdquo; &mdash; und berichtet, dass 48 % der AP-Fachleute eine hohe Ausnahmequote als eine ihrer größten Herausforderungen nennen. Der Bericht enthält jedoch <strong>keine Aufschlüsselung der Ausnahmen nach Ursache</strong> und <strong>keine bezifferte Senkung</strong> durch Automatisierung, er kann die 80 % also weder bestätigen noch widerlegen. Wirkmechanismus belegt, Größenordnung unsere: dieselbe Beweislage wie bei der OECD auf der indirekten Ebene.<br><br>Er setzt allerdings eine <strong>Obergrenze</strong>, und die wird jetzt durchgesetzt. Siehe den Rahmen zur Ausnahmesenkung neben dieser Zeile.' FROM roi_benchmarks WHERE key = 'error_elimination_pct';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Ardent Partners, Daten 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: marktdurchschnittliche Ausnahmequote 18,4 %; Best-in-Class 11,1 % gegenüber 20,9 % bei allen anderen. Beachten Sie, dass sie gegenüber 14 % in der Vorausgabe gestiegen ist. <strong>Nicht austauschbar mit der manuellen Fehlerquote von 10 %, mit der dieses Modell rechnet</strong>: Eine Ausnahme ist jede Rechnung, die einen manuellen Eingriff braucht, ein Fehler ist enger gefasst, und die beiden stillschweigend zu vertauschen würde eine Zeile des Business Case allein durch einen Definitionswechsel fast verdoppeln.' FROM roi_benchmarks WHERE key = 'exception_rate';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Ardent Partners: Best-in-Class gegenüber allen anderen', 'Ardent Partners, <em>The State of ePayables 2025</em>: Best-in-Class-Organisationen fahren eine Ausnahmequote von <strong>11,1 %</strong> gegenüber <strong>20,9 %</strong> bei allen anderen &mdash; eine Lücke von <strong>9,8 Prozentpunkten</strong>. Hier als OBERGRENZE verwendet, nicht als Ziel. Sie ist der gesamte beobachtete Unterschied zwischen dem am stärksten automatisierten Viertel des Marktes und allen übrigen, über sämtliche Ausnahmeursachen hinweg; E-Invoicing ist einer von vielen Faktoren, denn Best-in-Class verarbeitet zudem 51 % der Rechnungen durchgängig gegenüber 29 % und hat 1,4&times; mehr angebundene Lieferanten. Übersteigt der eigene Anspruch dieses Modells (Fehlerquote &times; beseitigte Fehler) 9,8 Punkte, behauptet es, dass E-Invoicing allein alles schlägt, was Best-in-Class-Organisationen zusammengenommen tun &mdash; und die Seite sagt das dann auch. <strong>Note B: Ardents Zahlen, unsere Subtraktion.</strong> Beachten Sie außerdem, dass Ardent keine Aufschlüsselung der Ausnahmen nach Ursache veröffentlicht; nichts hier belegt also, welcher Anteil dieser Lücke auf Erfassungsfehler entfällt.' FROM roi_benchmarks WHERE key = 'exception_reduction_pp';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — Ihre eigenen laufenden Kosten', 'Ein Platzhalter, kein Benchmark. Ihre eigenen laufenden Kosten sind hier die einzig sinnvolle Eingabe.' FROM roi_benchmarks WHERE key = 'internal_run_cost';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'BLS-Medianlohn, belastet mit dem BLS-Arbeitgeberkostenfaktor', 'US Bureau of Labor Statistics, Occupational Employment and Wage Statistics: Accountants and Auditors, Medianjahreslohn <strong>81.680 $</strong> (Mai 2024). Belastet mit <strong>&times;1,43</strong>, hergeleitet aus BLS Employer Costs for Employee Compensation (März 2026), wo Löhne und Gehälter 69,9 % der Gesamtvergütung in der Privatwirtschaft ausmachen &mdash; die Arbeitgeberkosten sind also Lohn / 0,699. Ergibt <strong>116.800 $</strong>. Note B statt A, weil beide Eingangsgrößen BLS-Primärdaten sind, <strong>die Multiplikation aber von uns stammt</strong> &mdash; dieselbe Grundlage, auf der die AR-Kosten je Rechnung mit B bewertet sind. Das ist der Satz für die Person, die Steuermeldung und Prüfungsvorbereitung macht, <em>nicht</em> für die Person, die Rechnungen erfasst &mdash; das sind verschiedene Tätigkeiten zum rund doppelten Preis, und bis zum 14. August 2026 hat ein einziges Feld beide bewertet. Gemeinkosten über die gesetzlichen Arbeitgeberkosten hinaus sind nicht enthalten; rechnen Sie sie hinzu, wenn Ihr eigener Vollkostensatz sie trägt.' FROM roi_benchmarks WHERE key = 'loaded_fte_cost';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'BLS-Medianlohn, belastet mit dem BLS-Arbeitgeberkostenfaktor', 'US Bureau of Labor Statistics, Occupational Employment and Wage Statistics: <strong>Data Entry Keyers</strong> (SOC 43-9021), Medianjahreslohn <strong>37.790 $</strong> (Mai 2023); zehntes Perzentil 28.250 $, neunzigstes 55.330 $. Belastet mit <strong>&times;1,43</strong> aus BLS Employer Costs for Employee Compensation (März 2026) ergibt das <strong>54.000 $</strong>. Note B: BLS-Eingangsdaten, unsere Multiplikation. <strong>Das ist ein US-Inhouse-Wert, und die Erfassung ist die am stärksten ausgelagerte Funktion im Finanzbereich</strong> &mdash; ein Shared-Service-Center in Krakau, Lissabon oder Manila liegt deutlich darunter, und wer seinen eigenen Satz kennt, sollte ihn verwenden. Beachten Sie außerdem, dass das BLS für diesen Beruf bis 2034 einen Rückgang um 6 % prognostiziert und ihn auf die Automatisierung routinemäßiger Buchhaltungsaufgaben zurückführt &mdash; genau der Effekt, den dieses Modell bewertet.' FROM roi_benchmarks WHERE key = 'loaded_fte_cost_entry';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'HMRC-Konsultation — darin ohne Quellenangabe', 'Dieselbe HMRC-/DBT-Konsultation: &ldquo;Manually entering supplier invoice data has an average error rate of approximately 10%.&rdquo; Eine Quelle für diese Zahl wird im Dokument nicht genannt.' FROM roi_benchmarks WHERE key = 'manual_error_rate';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Ardent Partners, Daten 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: <strong>51,4 %</strong> der Rechnungen gehen elektronisch ein, 48,6 % auf Papier. Nur dazu verwendet, die gemischten Marktdurchschnittskosten von 9,84 $ in ihre manuellen und elektronischen Bestandteile aufzuteilen, damit der eigene Anteil eines Lesers auf die richtige Basis angewendet werden kann. <strong>Note B statt A, weil Ardent &ldquo;electronically&rdquo; nicht definiert</strong> &mdash; der Bericht gibt keine Aufschlüsselung nach Format, es ist also nicht belegt, ob per E-Mail versandte PDFs mitgezählt werden. Gemessen, was für Note A spricht; ohne Nenner veröffentlicht, was dagegen spricht.' FROM roi_benchmarks WHERE key = 'market_einvoice_share';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Ein einzelner NHS-Trust — eine Anekdote, kein Benchmark', 'Leitfaden des UK Small Business Commissioner, Seite aktualisiert am 16. Jan. 2026: Ein NHS-Trust verarbeitete E-Rechnungen binnen 24 Stunden statt 10 Tagen auf Papier, wurde fast doppelt so schnell bezahlt und verzeichnete rund 15 % weniger Lieferantenrückfragen. <strong>Eine einzelne, nicht genannte und nicht datierte Organisation.</strong> Nur richtungsweisend; in diesem Modell nie beziffert.' FROM roi_benchmarks WHERE key = 'nhs_query_reduction';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — hängt vollständig von Ihrem Anbieter ab', 'Ein Platzhalter, kein Benchmark. Die Anbieterpreise in diesem Markt unterscheiden sich um eine Zehnerpotenz und werden selten veröffentlicht.' FROM roi_benchmarks WHERE key = 'platform_cost_year';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — ein ungefährer Multiplikator je Dokument', 'Ein Platzhalter, kein Benchmark. Die Anbieterpreise in diesem Markt unterscheiden sich um eine Zehnerpotenz und werden selten veröffentlicht; USD 0,40 je Dokument ist ein gerundeter Größenordnungswert für Netzwerk- und Plattformgebühren, kein erhobener Durchschnitt. Der daraus errechnete Jahreswert sollte durch das Angebot Ihres Anbieters ersetzt werden.' FROM roi_benchmarks WHERE key = 'platform_fee_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'ATO / Deloitte: 15 Min. für eine Bearbeitungsausnahme', 'Australian Taxation Office, <em>Peppol eInvoicing value assessment</em>. Ausnahmen bei Eingangsrechnungen, mit der durchschnittlich zugerechneten Zeit für ihre Korrektur: <strong>strittige Zahlung 20 Min.</strong> (10 % der Rechnungen), <strong>Bearbeitungsausnahme 15 Min.</strong> (24 %), <strong>verspätete Zahlung 5 Min.</strong> (48 %), <strong>Datenrichtigkeit 5 Min.</strong> (3,6 %). Standardmäßig die Bearbeitungsausnahme mit 15 Minuten, weil diese Zeile Nachfassen, Neuerfassen und erneute Freigabe abdeckt und nicht einen korrigierten Tastenanschlag &mdash; setzen Sie sie auf 5, wenn Sie nur den Tastenanschlag meinen, oder auf 20, wenn Ihre Ausnahmen tatsächlich strittig sind.<br><br><strong>Das ist Arbeitsaufwand, keine Durchlaufzeit.</strong> Die ATO rechnet diese Minuten mit Lohndaten des Australian Bureau of Statistics in Geld um, was nur für tatsächliche Bearbeitungszeit zulässig ist. APQC veröffentlicht größere Stichproben zur Ausnahmebehebung &mdash; 5,0 Arbeitstage (n=461) und 4,0 Kalendertage (n=2.861) &mdash; doch beide sind nach eigener Definition <em>Durchlaufzeiten</em>, und eine Multiplikation mit einem Lohnsatz ergäbe rund 1.000 $ je Ausnahme.<br><br><strong>Note B, und der Grund liegt in der Herkunft, nicht im Herausgeber.</strong> Die ATO ist primär und frei zugänglich, führt die zugrunde liegenden Schätzungen aber auf Deloitte Access Economics zurück und datiert sie auf 2016; für die Zeiten selbst ist keine Stichprobengröße veröffentlicht, und der Deloitte-Bericht ist öffentlich nicht zu beschaffen. Ob gemessen oder modelliert, ist nicht belegt &mdash; und das ist Note-B-Verhalten, nicht A.<br><br><strong>Beachten Sie, dass die Quote daneben aus einer anderen Quelle stammt.</strong> Dieses Modell verwendet die manuelle Fehlerquote von 10 % der HMRC; die eigene Ausnahmequote der ATO für Datenrichtigkeit liegt bei 3,6 %. Das sind nicht dieselben Messungen &mdash; die HMRC zählt durch Erfassung entstandene Fehler, die ATO zählt ausgelöste Ausnahmen &mdash; wenn Sie aber durchgängig eine Methodik wollen, setzen Sie die Fehlerquote ebenfalls auf 3,6 %.' FROM roi_benchmarks WHERE key = 'rework_minutes';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Es gibt keinen Benchmark — unsere Schätzung', 'Unsere Schätzung. Kein Analystenhaus veröffentlicht einen belastbaren Wert für die Kosten je Ausnahme; ihn durch Ihren eigenen zu ersetzen ist in jedem Fall besser als unsere Schätzung.' FROM roi_benchmarks WHERE key = 'rework_per_error';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Ardent Partners, Daten 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: Best-in-Class-AP-Organisationen wenden <strong>12,8 %</strong> der Arbeitszeit für Lieferantenrückfragen auf, gegenüber <strong>24,0 %</strong> bei allen anderen; der Marktdurchschnitt für die Zeit im Umgang mit Lieferanten insgesamt liegt bei 21,9 %. Gemessen, primär und zurechenbar. <strong>Entscheidend ist, dass diese Kennzahl nicht Teil von Ardents Best-in-Class-Definition ist</strong> &mdash; genau das macht sie dort brauchbar, wo die Durchlaufzeitlücke es nicht ist. Sie bleibt ein Zusammenhang mit leistungsstarker Kreditorenbuchhaltung insgesamt: Ardent isoliert E-Invoicing nicht und berichtet nur, dass Spitzenreiter 1,4&times; mehr elektronisch fakturierfähige Lieferanten und 1,8&times; mehr durchgängige Verarbeitung haben. <strong>Trägt in diesem Modell keinen Wert.</strong>' FROM roi_benchmarks WHERE key = 'supplier_inquiry_time';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — unsere Annahme, als Verhältnis', 'Eine Obergrenze für den Satz je Land, weil die Größenordnung eine Annahme ist und eine ungedeckelte Annahme davonläuft: Angerechnet werden höchstens <strong>20 %</strong> des AP-Aufwands, der sich aus Ihrem Volumen ergibt, wie viele Länder auch ausgewählt sind. Am 14. August 2026 von 36 % gesenkt, <strong>zeitgleich mit der Anhebung des Satzes für die Steuer-Vollzeitkraft von 62.000 $ auf 116.800 $</strong>, weil beide miteinander multipliziert werden und eine Korrektur ohne die andere den Fehler verstärkt statt behebt. 36 % hätten bedeutet, dass E-Invoicing allein den größten Teil einer Steuerfunktion beseitigt, was nicht vertretbar ist; 20 % sind rund 1,67 Vollzeitkräfte über 25 Clearance-Länder, also je etwa drei Wochen im Jahr an geringerem Abgleichs- und Prüfungsvorbereitungsaufwand. Weiterhin unsere Zahl, weiterhin Note D und weiterhin die Zahl, über die zuerst zu streiten ist.' FROM roi_benchmarks WHERE key = 'tax_effort_cap';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'PLATZHALTER — unsere Annahme, als Verhältnis', 'Unsere Annahme, kein Benchmark: Jedes Land mit Clearance oder Meldung auf Rechnungsebene wird so modelliert, dass es 1,8 % des aus Ihrem Volumen abgeleiteten AP-Aufwands in den Umfang für geringere Steuermeldung und Prüfungsvorbereitung bringt. Dafür wird nichts behauptet. Der Wert ist als VERHÄLTNIS ausgedrückt und nicht als Personalzahl, damit er mit der Unternehmensgröße skaliert; beim Seitenstandard von 100.000 AP-Rechnungen entspricht er genau den pauschalen 0,15 Vollzeitkräften je Land, die er ersetzt.' FROM roi_benchmarks WHERE key = 'tax_effort_per_jurisdiction';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Vielfach zitiert, kausal nicht belastbar', 'Häufig zitierte Rückgänge der Umsatzsteuerlücke für Ungarn (10,4 %&rarr;4,4 %), Italien (21,8 %&rarr;10,8 %), Polen (12,5 %&rarr;3,3 %) und Spanien (6,1 %&rarr;0,8 %), 2019&ndash;21. <strong>Zwei Korrekturen aus der Überprüfung:</strong> Es handelt sich um Zahlen der Europäischen Kommission / CASE, nicht der OECD; und die eigenen Länderanalysen der Kommission für Ungarn, Italien und Polen führen die Veränderung auf die konjunkturelle Erholung nach der Pandemie zurück, nicht auf die digitale Meldung. <strong>Trägt in diesem Modell nirgends einen Wert.</strong>' FROM roi_benchmarks WHERE key = 'vat_gap_context';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'de', '', 'Unsere Annahme — ein Meldungsaufbau auf einer vorhandenen Plattform', 'Unsere Annahme, kein Benchmark. Ein EU-Mitgliedstaat mit einer nationalen Frist vor Juli 2030 steht vor einer zweiten Verpflichtung: der Meldepflicht aus der Richtlinie (EU) 2025/516 des Rates. Sie wird mit <strong>der Hälfte</strong> einer vollen Länderintegration modelliert, weil bis dahin Plattform, Zugangspunktanbindung und Stammdaten bereits bestehen und Anbieterauswahl und Vertragsabschluss einmal auf Programmebene modelliert werden und sich nicht wiederholen. Wirklich neu sind der Meldeauszug, die Übermittlung an die Steuerbehörde und deren Test. Für die Zahl wird nichts behauptet: Eine volle zweite Integration würde eine einmal gekaufte Plattform doppelt berechnen, und null würde die Frist zeigen und die Arbeit leugnen. Wenn Ihr Aufbau für 2027 bereits einen konformen Meldeauszug erzeugt, senken Sie den Wert.' FROM roi_benchmarks WHERE key = 'vida_second_wave_ratio';

-- ---- 7 phases --------------------------------------------------------
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'Anbieterauswahl', 'Auf Programmebene: einmal für das gesamte Programm, nicht je Land. Marktscreening, Ausschreibung, Demos und Referenzgespräche. Bemessen am komplexesten Land im Umfang — ein einziges Clearance-Regime in der Liste heißt, dass Sie eine clearancefähige Plattform kaufen.' FROM roi_phases WHERE key = 'vendor';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'Vertragsabschluss', 'Auf Programmebene: einmal, nicht je Land. Kaufmännisches, Recht, Sicherheitsprüfung, Unterschrift. Die Phase, die am häufigsten verrutscht, und sie liegt vor jedem Länder-Arbeitsstrang — deshalb ist hier die Beschaffung der kritische Pfad und nicht die Umsetzung.' FROM roi_phases WHERE key = 'contract';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'Mobilisierung', 'Je Land. Team aufgestellt, Umfang mit den lokalen Finanz- und Steuerverantwortlichen bestätigt, Zugang zum ERP des Landes eingerichtet. Praktikerschätzung für einen Rollout auf einer bereits vorhandenen Plattform — keine ERP-Programm-Mobilisierung, die um ein Vielfaches länger dauert.' FROM roi_phases WHERE key = 'mobilise';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'Design', 'Je Land. Die lokale Vorgabe auf Ihre Daten abbilden: Feldzuordnung, Lücken in den Stammdaten, der Clearance- oder Meldefluss, Archivierung. Skaliert mit der Komplexität des Landes und mit der Zahl der Systeme, die zuliefern müssen.' FROM roi_phases WHERE key = 'design';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'Aufbau', 'Je Land. Konfigurieren und integrieren — Konnektor, Transformation, Validierung, Fehlerbehandlung. Die längste technische Phase und der Ort der eigentlichen Arbeit. Skaliert mit Komplexität und Systemzahl genauso wie das Design.' FROM roi_phases WHERE key = 'build';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'UAT &amp; Umstellung', 'Je Land. Ende-zu-Ende-Test mit der Steuerbehörde oder dem Zugangspunkt, Zertifizierung, wo ein Land sie verlangt, dann Umstellung auf den Echtbetrieb. Kurz, weil ein E-Invoicing-UAT ein enger Integrationstest ist — es hängt aber an Rücklaufzeiten der Behörde, die Sie nicht steuern.' FROM roi_phases WHERE key = 'uat';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'de', 'Prozessumstellung &amp; Schulung', 'Erscheint nur, wenn die Automatisierung der AP-Prozesse im Umfang ist. Prozessneugestaltung, Nachschulung, Lieferantenanbindung — die Phase, die die direkten Einsparungen real macht. Länger als die technischen Phasen, und sie landet im Fachbereich, nicht in der IT, weshalb Compliance allein sie nicht hebt.' FROM roi_phases WHERE key = 'change';

